package genesismesh

import (
	"crypto/ed25519"
	"encoding/base64"
	"encoding/json"
	"os"
	"reflect"
	"testing"
	"time"
)

// Shared conformance suite "audit" (v1.5.0), generated by the Python
// reference (genesismesh/conformance/generate_vectors.py audit) and copied
// unchanged. This SDK runs the vectors of what it verifies: the signed forms
// of the new records, the NA key history, the keys valid at a time, the time
// a record read alone is placed at, and decisions judged with a history.
// Audit packs (and their report cells, ranges and changes files), evidence
// exports, registry keys, anchors and the completeness check are verified by
// the core and genesis-mesh-verify.

type auditVector struct {
	ID          string                     `json:"id"`
	Kind        string                     `json:"kind"`
	Description string                     `json:"description"`
	Model       string                     `json:"model"`
	Record      json.RawMessage            `json:"record"`
	Input       map[string]json.RawMessage `json:"input"`
	Expected    json.RawMessage            `json:"expected"`
}

var auditKindsNotRun = map[string]bool{
	"pack": true, "verify_export": true, "verify_range": true, "verify_anchors": true, "completeness": true,
	"registry_keys": true, "report_cell": true, "changes_file": true,
}

func loadAuditVectors(t *testing.T) []auditVector {
	t.Helper()
	raw, err := os.ReadFile("testdata/conformance/audit.json")
	if err != nil {
		t.Fatal(err)
	}
	var suite struct {
		Suite   string        `json:"suite"`
		Vectors []auditVector `json:"vectors"`
	}
	if err := json.Unmarshal(raw, &suite); err != nil {
		t.Fatal(err)
	}
	if suite.Suite != "audit" || len(suite.Vectors) == 0 {
		t.Fatalf("unexpected suite %q with %d vectors", suite.Suite, len(suite.Vectors))
	}
	return suite.Vectors
}

func auditVectorByID(t *testing.T, id string) auditVector {
	t.Helper()
	for _, v := range loadAuditVectors(t) {
		if v.ID == id {
			return v
		}
	}
	t.Fatalf("no vector %s", id)
	return auditVector{}
}

func historyOf(t *testing.T, input map[string]json.RawMessage) *NAKeyHistory {
	t.Helper()
	res, err := VerifyKeyHistory(input["genesis"], input["successions"], text(t, input["root_public_key"]))
	if err != nil || !res.Verified {
		t.Fatalf("history: %+v %v", res, err)
	}
	return res.History
}

func isoOrNil(v *time.Time) interface{} {
	if v == nil {
		return nil
	}
	return v.UTC().Format("2006-01-02T15:04:05Z")
}

func keyDicts(h *NAKeyHistory) []interface{} {
	out := []interface{}{}
	if h == nil {
		return out
	}
	for _, k := range h.Keys {
		var id interface{}
		if k.KeyID != "" {
			id = k.KeyID
		}
		out = append(out, map[string]interface{}{
			"key_sequence": k.KeySequence, "key_id": id, "public_key": k.PublicKey,
			"valid_from": isoOrNil(k.ValidFrom), "succeeded_at": isoOrNil(k.SucceededAt),
			"valid_to": isoOrNil(k.ValidTo), "valid_to_enforced": k.ValidToEnforced,
		})
	}
	return out
}

func TestConformanceAuditVectors(t *testing.T) {
	kinds := map[string]int{}
	for _, v := range loadAuditVectors(t) {
		v := v
		kinds[v.Kind]++
		if auditKindsNotRun[v.Kind] {
			continue
		}
		t.Run(v.ID, func(t *testing.T) {
			var got interface{}
			switch v.Kind {
			case "canonical_form":
				record, err := decodeObject(v.Record, "record")
				if err != nil {
					t.Fatal(err)
				}
				c, err := receivedCanonical(v.Model, record)
				if err != nil {
					t.Fatal(err)
				}
				got = map[string]interface{}{"canonical": c, "digest": sha256Hex(c)}
			case "key_history":
				res, err := VerifyKeyHistory(v.Input["genesis"], v.Input["successions"], text(t, v.Input["root_public_key"]))
				if err != nil {
					t.Fatal(err)
				}
				failures := []interface{}{}
				if !res.Verified {
					failures = append(failures, map[string]interface{}{"key_sequence": res.KeySequence, "reason": res.Reason})
				}
				got = map[string]interface{}{"verified": res.Verified, "failures": failures, "keys": keyDicts(res.History)}
			case "key_at":
				at, err := ParseTimestamp(text(t, v.Input["at"]))
				if err != nil {
					t.Fatal(err)
				}
				got = map[string]interface{}{"keys": historyOf(t, v.Input).KeysAt(at)}
			case "decision_at_record_time":
				history := historyOf(t, v.Input)
				now, _ := ParseTimestamp(text(t, v.Input["now"]))
				atRecord, err := VerifyBoundaryDecision(v.Input["decision"], DecisionVerifyOptions{KeyHistory: history, AtRecordTime: true})
				if err != nil {
					t.Fatal(err)
				}
				atNow, err := VerifyBoundaryDecision(v.Input["decision"], DecisionVerifyOptions{KeyHistory: history, Now: now})
				if err != nil {
					t.Fatal(err)
				}
				got = map[string]interface{}{"at_record_time": atRecord.Reason, "now": atNow.Reason}
			case "record_time":
				var field interface{}
				if f, ok := NARecordTimeFields[v.Model]; ok {
					field = f
				}
				got = map[string]interface{}{"field": field}
			default:
				t.Fatalf("vector kind %q is neither run nor listed as not run", v.Kind)
			}
			gotRaw, _ := json.Marshal(got)
			var g, w interface{}
			_ = json.Unmarshal(gotRaw, &g)
			_ = json.Unmarshal(v.Expected, &w)
			if !reflect.DeepEqual(g, w) {
				t.Fatalf("%s\n got:  %s\n want: %s", v.Description, gotRaw, v.Expected)
			}
		})
	}
	for _, kind := range []string{"canonical_form", "key_history", "key_at", "decision_at_record_time", "record_time"} {
		if kinds[kind] == 0 {
			t.Errorf("no %s vectors", kind)
		}
	}
}

// ── a succession built and signed here ─────────────────────────────────────

type successionWorld struct {
	root, na1, na2 ed25519.PrivateKey
	genesis        []byte
	successions    []byte
	effective      time.Time
	history        *NAKeyHistory
}

func seededKey(b byte) ed25519.PrivateKey {
	seed := make([]byte, ed25519.SeedSize)
	for i := range seed {
		seed[i] = b
	}
	return ed25519.NewKeyFromSeed(seed)
}

func pubOf(k ed25519.PrivateKey) string {
	return base64.StdEncoding.EncodeToString(k.Public().(ed25519.PublicKey))
}

type signer struct {
	keyID string
	key   ed25519.PrivateKey
}

// signedWith sets the record's signatures: one by each signer over its received form.
func signedWith(t *testing.T, model string, record object, signers ...signer) object {
	t.Helper()
	c, err := receivedCanonical(model, record)
	if err != nil {
		t.Fatal(err)
	}
	sigs := []interface{}{}
	for _, s := range signers {
		sigs = append(sigs, map[string]interface{}{
			"key_id": s.keyID, "sig": base64.StdEncoding.EncodeToString(ed25519.Sign(s.key, []byte(c))),
		})
	}
	record["signatures"] = sigs
	return record
}

func mustJSON(t *testing.T, v interface{}) []byte {
	t.Helper()
	raw, err := json.Marshal(v)
	if err != nil {
		t.Fatal(err)
	}
	return raw
}

// genesisFor is a genesis block in the form the reference writes, signed by root.
func genesisFor(t *testing.T, sovereign string, root, na ed25519.PrivateKey) object {
	t.Helper()
	return signedWith(t, "GenesisBlock", object{
		"network_name": sovereign, "network_version": "v1", "root_public_key": pubOf(root),
		"network_authority": map[string]interface{}{
			"public_key": pubOf(na), "valid_from": "2026-01-01T00:00:00Z", "valid_to": "2026-04-01T00:00:00Z",
		},
		"allowed_crypto_suites": []interface{}{"ed25519", "x25519"}, "allowed_transports": []interface{}{"quic", "wireguard"},
		"policy_manifest": map[string]interface{}{"hash": "sha256:test", "url": nil}, "bootstrap_anchors": []interface{}{},
	}, signer{"root", root})
}

// successionFor is the first succession, previous to next at effective, with its three
// signatures: the root key's, the new key's and the outgoing key's.
func successionFor(t *testing.T, sovereign string, root, previous, next ed25519.PrivateKey, effective time.Time) object {
	t.Helper()
	return signedWith(t, "KeySuccessionRecord", object{
		"succession_id": "00000000-0000-4000-8000-000000000001", "sovereign_id": sovereign, "key_sequence": 2,
		"previous_key_id": "na-1", "previous_public_key": pubOf(previous), "new_key_id": "na-2",
		"new_public_key": pubOf(next), "effective_at": iso(effective),
		"new_valid_to": iso(effective.AddDate(2, 0, 0)), "issued_at": iso(effective.AddDate(0, 0, -9)),
	}, signer{"root", root}, signer{"na-2", next}, signer{"na-1", previous})
}

func iso(t time.Time) string { return t.UTC().Format("2006-01-02T15:04:05Z") }

// newSuccessionWorld: the genesis key na-1, succeeded by na-2 on 2026-03-01.
func newSuccessionWorld(t *testing.T) successionWorld {
	t.Helper()
	w := successionWorld{root: seededKey(0x71), na1: seededKey(0x72), na2: seededKey(0x73)}
	w.effective = time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC)
	w.genesis = mustJSON(t, genesisFor(t, "sovereign-s", w.root, w.na1))
	w.successions = mustJSON(t, []interface{}{successionFor(t, "sovereign-s", w.root, w.na1, w.na2, w.effective)})
	res, err := VerifyKeyHistory(w.genesis, w.successions, pubOf(w.root))
	if err != nil || !res.Verified {
		t.Fatalf("history: %+v %v", res, err)
	}
	w.history = res.History
	return w
}

// decisionAt is the audit suite's decision, made at madeAt, valid for lifetime and signed by key.
func decisionAt(t *testing.T, madeAt time.Time, lifetime time.Duration, key ed25519.PrivateKey) []byte {
	t.Helper()
	d := withValue(t, auditVectorByID(t, "decision-at-record-time").Input["decision"], "decision_made_at", iso(madeAt))
	d["decision_valid_until"] = iso(madeAt.Add(lifetime))
	return resigned(t, d, key, decisionOmittedWhenAbsent...)
}

func TestDecisionsSignedBeforeAndAfterASuccession(t *testing.T) {
	w := newSuccessionWorld(t)
	day := 24 * time.Hour
	cases := []struct {
		name     string
		madeAt   time.Time
		lifetime time.Duration
		key      ed25519.PrivateKey
		want     string
	}{
		{"old key before the succession", w.effective.Add(-time.Hour), 5 * time.Minute, w.na1, "authorized"},
		{"new key before the succession", w.effective.Add(-time.Hour), 5 * time.Minute, w.na2, "na_key_not_valid_at_time"},
		{"new key when it takes effect", w.effective, 5 * time.Minute, w.na2, "authorized"},
		{"old key during the hand-over", w.effective.Add(299 * time.Second), 5 * time.Minute, w.na1, "authorized"},
		{"old key at the end of the hand-over", w.effective.Add(SuccessionHandover), 5 * time.Minute, w.na1, "na_key_not_valid_at_time"},
		{"old key long after", w.effective.Add(30 * day), 5 * time.Minute, w.na1, "na_key_not_valid_at_time"},
		{"new key long after", w.effective.Add(30 * day), 5 * time.Minute, w.na2, "authorized"},
		{"new key at its valid_to", time.Date(2028, 3, 1, 0, 0, 0, 0, time.UTC), 5 * time.Minute, w.na2, "na_key_not_valid_at_time"},
		{"the root key", w.effective, 5 * time.Minute, w.root, "invalid_signature"},
		// The old key's end, the hand-over and the lifetime cap: 600 s past the succession.
		{"old key, valid up to the cap", w.effective.Add(299 * time.Second), 301 * time.Second, w.na1, "authorized"},
		{"old key, valid past the cap", w.effective.Add(299 * time.Second), 302 * time.Second, w.na1, "decision_outlives_key"},
		{"old key, a day long before the succession", w.effective.Add(-time.Hour), day, w.na1, "decision_outlives_key"},
		{"new key, a day long", w.effective.Add(time.Hour), day, w.na2, "authorized"},
		{"new key, valid past its valid_to", time.Date(2028, 2, 29, 0, 0, 0, 0, time.UTC), 2 * day, w.na2, "decision_outlives_key"},
	}
	for _, c := range cases {
		raw := decisionAt(t, c.madeAt, c.lifetime, c.key)
		got, err := VerifyBoundaryDecision(raw, DecisionVerifyOptions{KeyHistory: w.history, Now: c.madeAt.Add(time.Minute)})
		if err != nil || got.Reason != c.want {
			t.Errorf("%s: %+v %v, want %s", c.name, got, err, c.want)
		}
		// Judged at its own time, years later, the same outcome.
		got, err = VerifyBoundaryDecision(raw, DecisionVerifyOptions{KeyHistory: w.history, AtRecordTime: true,
			Now: c.madeAt.Add(5 * 365 * day)})
		if err != nil || got.Reason != c.want {
			t.Errorf("%s at record time: %+v %v, want %s", c.name, got, err, c.want)
		}
	}
}

func TestWithoutAKeyHistoryDecisionsVerifyAsBefore(t *testing.T) {
	w := newSuccessionWorld(t)
	// A plain key list is valid at every time: no window, no lifetime cap, no new reason.
	madeAt := w.effective.Add(-time.Hour)
	raw := decisionAt(t, madeAt, 5*time.Minute, w.na2)
	now := madeAt.Add(time.Minute)
	got, err := VerifyBoundaryDecision(raw, DecisionVerifyOptions{
		OperatorPublicKeys: []string{pubOf(w.na1), pubOf(w.na2)}, Now: now,
	})
	if err != nil || got.Reason != "authorized" {
		t.Errorf("plain keys: %+v %v", got, err)
	}
	got, err = VerifyBoundaryDecision(raw, DecisionVerifyOptions{OperatorPublicKeys: []string{pubOf(w.na1)}, Now: now})
	if err != nil || got.Reason != "invalid_signature" {
		t.Errorf("another key: %+v %v", got, err)
	}
	// NAKeysValidAlways reads a list as before.
	got, err = VerifyBoundaryDecision(raw, DecisionVerifyOptions{KeyHistory: NAKeysValidAlways([]string{pubOf(w.na2)}), Now: now})
	if err != nil || got.Reason != "authorized" {
		t.Errorf("keys valid always: %+v %v", got, err)
	}
	long := decisionAt(t, madeAt, 365*24*time.Hour, w.na1)
	got, err = VerifyBoundaryDecision(long, DecisionVerifyOptions{OperatorPublicKeys: []string{pubOf(w.na1)}, Now: now})
	if err != nil || got.Reason != "authorized" {
		t.Errorf("a year long, plain keys: %+v %v", got, err)
	}
	if _, err := VerifyBoundaryDecision(raw, DecisionVerifyOptions{OperatorPublicKeys: []string{pubOf(w.na1)}, KeyHistory: w.history}); err == nil {
		t.Error("keys and a history were both accepted")
	}
	// Expired now, valid when made.
	expired, err := VerifyBoundaryDecision(raw, DecisionVerifyOptions{OperatorPublicKeys: []string{pubOf(w.na2)}, Now: madeAt.Add(time.Hour)})
	if err != nil || expired.Reason != "decision_expired" {
		t.Errorf("expired: %+v %v", expired, err)
	}
	atRecord, err := VerifyBoundaryDecision(raw, DecisionVerifyOptions{OperatorPublicKeys: []string{pubOf(w.na2)}, AtRecordTime: true})
	if err != nil || atRecord.Reason != "authorized" {
		t.Errorf("at record time: %+v %v", atRecord, err)
	}
}

func TestAgreementsArePlacedAtTheirTermsAndVouchWhileTheKeyIsAccepted(t *testing.T) {
	v := interopVector(t, "agr-001")
	offererKeys := strings_(t, v.Input["offerer_public_keys"])
	responderKeys := strings_(t, v.Input["responder_public_keys"])
	offerer := conformanceKey(t, offererKeys)
	if pubOf(offerer) != offererKeys[0] {
		t.Fatal("unexpected offerer key")
	}
	validFrom := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC) // agreed_terms.valid_from, signed
	root, next := seededKey(0x74), seededKey(0x75)
	historyWith := func(effective time.Time) *NAKeyHistory {
		res, err := VerifyKeyHistory(mustJSON(t, genesisFor(t, "offerer", root, offerer)),
			mustJSON(t, []interface{}{successionFor(t, "offerer", root, offerer, next, effective)}), pubOf(root))
		if err != nil || !res.Verified {
			t.Fatalf("history: %+v %v", res, err)
		}
		return res.History
	}
	// The offerer's agreement key is its genesis key, succeeded a day after the terms start.
	effective := validFrom.Add(24 * time.Hour)
	later := historyWith(effective)
	responder := NAKeysValidAlways(responderKeys)
	for _, c := range []struct {
		name string
		now  time.Time
		want string
	}{
		{"before the succession", effective.Add(-time.Hour), "accepted"},
		{"during the hand-over", effective.Add(299 * time.Second), "accepted"},
		{"once the hand-over ends", effective.Add(SuccessionHandover), "invalid_offerer_signature"},
	} {
		got, err := VerifyAgreementWithKeyHistory(v.Input["agreement"], later, responder, "", c.now)
		if err != nil || got.Reason != c.want {
			t.Errorf("%s: %+v %v, want %s", c.name, got, err, c.want)
		}
	}
	// Succeeded before the terms start: the key was not valid then. established_at,
	// outside the signed form, does not move the agreement.
	earlier := historyWith(validFrom.Add(-24 * time.Hour))
	moved := mustJSON(t, withValue(t, v.Input["agreement"], "established_at", "2025-06-01T00:00:00Z"))
	got, err := VerifyAgreementWithKeyHistory(moved, earlier, responder, "", validFrom.Add(-48*time.Hour))
	if err != nil || got.Reason != "invalid_offerer_signature" {
		t.Errorf("succeeded before the terms: %+v %v", got, err)
	}
	// Without a history the same agreement verifies as before.
	plain, err := VerifyAgreement(moved, offererKeys, responderKeys, "")
	if err != nil || plain.Reason != "accepted" {
		t.Errorf("plain keys: %+v %v", plain, err)
	}
	if _, err := VerifyAgreementWithKeyHistory(v.Input["agreement"], later, nil, "", time.Time{}); err == nil {
		t.Error("a missing history was accepted")
	}
}

func TestKeyHistoryFromTheNAResponse(t *testing.T) {
	w := newSuccessionWorld(t)
	var genesis, successions interface{}
	_ = json.Unmarshal(w.genesis, &genesis)
	_ = json.Unmarshal(w.successions, &successions)
	body := mustJSON(t, map[string]interface{}{
		"sovereign_id": "sovereign-s", "root_public_key": "not trusted", "handover_seconds": 300,
		"genesis": genesis, "successions": successions, "keys": []interface{}{}, "signing_key_sequence": 2,
	})
	res, err := VerifyKeyHistoryResponse(body, pubOf(w.root))
	if err != nil || !res.Verified || !reflect.DeepEqual(res.History.AllKeys(), []string{pubOf(w.na1), pubOf(w.na2)}) {
		t.Fatalf("response: %+v %v", res, err)
	}
	// Another root key: the history proves nothing.
	res, err = VerifyKeyHistoryResponse(body, pubOf(w.na1))
	if err != nil || res.Verified || res.Reason != "genesis_root_mismatch" || res.History != nil {
		t.Fatalf("another root: %+v %v", res, err)
	}
	if _, err := VerifyKeyHistory(w.genesis, w.successions, ""); err == nil {
		t.Error("no root key was accepted")
	}
}

func TestSuccessionSignaturesAndForm(t *testing.T) {
	w := newSuccessionWorld(t)
	base := func() object {
		var list []map[string]interface{}
		_ = json.Unmarshal(w.successions, &list)
		return object(list[0])
	}
	check := func(name string, record object, wantReason string, wantPosition int) {
		t.Helper()
		res, err := VerifyKeyHistory(w.genesis, mustJSON(t, []interface{}{record}), pubOf(w.root))
		if err != nil || res.Reason != wantReason || res.KeySequence != wantPosition {
			t.Errorf("%s: %+v %v, want %s at %d", name, res, err, wantReason, wantPosition)
		}
	}
	root, na1, na2 := signer{"root", w.root}, signer{"na-1", w.na1}, signer{"na-2", w.na2}
	check("root and outgoing key only", signedWith(t, "KeySuccessionRecord", base(), root, na1),
		"succession_invalid_new_key_signature", 2)
	check("root and new key only", signedWith(t, "KeySuccessionRecord", base(), root, na2),
		"succession_invalid_previous_signature", 2)
	check("new and outgoing key only", signedWith(t, "KeySuccessionRecord", base(), na2, na1),
		"succession_invalid_root_signature", 2)
	// An unknown field signed by the new key alone is still its signer's: unknown_field.
	unknown := base()
	unknown["extra"] = "x"
	check("unknown field signed by the new key", signedWith(t, "KeySuccessionRecord", unknown, na2), "unknown_field", 2)
	backdated := base()
	backdated["issued_at"] = "2026-03-01T00:00:01Z"
	check("issued after it takes effect", signedWith(t, "KeySuccessionRecord", backdated, root, na2, na1), "succession_backdated", 2)
	rootAsKey := base()
	rootAsKey["new_public_key"] = pubOf(w.root)
	check("the root key as the next key", signedWith(t, "KeySuccessionRecord", rootAsKey, root, root, na1), "succession_key_reused", 2)
	// The reference gives a record without an id a fresh one and refuses the form.
	noID := base()
	delete(noID, "succession_id")
	check("signed without an id", signedWith(t, "KeySuccessionRecord", noID, root, na2, na1), "non_canonical_form", 2)
	noID["key_sequence"] = 3
	check("changed after signing", noID, "invalid_signature", 3)
}

func TestTheGenesisBlockIsStrict(t *testing.T) {
	w := newSuccessionWorld(t)
	check := func(name string, genesis object, want string) {
		t.Helper()
		res, err := VerifyKeyHistory(mustJSON(t, genesis), nil, pubOf(w.root))
		if err != nil || res.Reason != want || res.KeySequence != 1 {
			t.Errorf("%s: %+v %v, want %s", name, res, err, want)
		}
	}
	plain := func() object { return genesisFor(t, "sovereign-s", w.root, w.na1) }
	unknown := plain()
	unknown["extra"] = true
	check("unknown field, signed", signedWith(t, "GenesisBlock", unknown, signer{"root", w.root}), "unknown_field")
	unsigned := plain()
	unsigned["extra"] = true
	check("unknown field, not signed", unsigned, "genesis_invalid_signature")
	loose := plain()
	loose["network_authority"].(map[string]interface{})["valid_to"] = "2026-04-01T00:00:00+00:00"
	check("timestamp not in canonical form, signed", signedWith(t, "GenesisBlock", loose, signer{"root", w.root}), "non_canonical_form")
	short := plain()
	delete(short, "bootstrap_anchors")
	check("a field the reference writes left out, signed", signedWith(t, "GenesisBlock", short, signer{"root", w.root}), "non_canonical_form")
	check("missing its NA", object{"network_name": "sovereign-s"}, "genesis_invalid")
}

func TestRecordTimeFieldsAreTimestamps(t *testing.T) {
	for model, field := range NARecordTimeFields {
		spec, ok := canonicalRegistry.Models[model]
		if !ok || spec.Fields[field] != "timestamp" {
			t.Errorf("%s.%s is not a timestamp of the registry", model, field)
		}
	}
}
